package com.imperium.saveeditor;
import android.app.*;import android.os.*;import android.content.*;import android.net.*;import android.webkit.*;import android.widget.*;import android.util.*;import java.io.*;
public class MainActivity extends Activity{
WebView web;ValueCallback<Uri[]> callback;byte[] pending;
public void onCreate(Bundle b){super.onCreate(b);web=new WebView(this);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setAllowFileAccess(true);web.getSettings().setAllowContentAccess(true);web.addJavascriptInterface(new Bridge(),"AndroidSave");web.setWebViewClient(new WebViewClient());web.setWebChromeClient(new WebChromeClient(){public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> c,FileChooserParams p){callback=c;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");startActivityForResult(i,101);return true;}});setContentView(web);web.loadUrl("file:///android_asset/index.html");}
public class Bridge{@JavascriptInterface public void exportSave(String s){pending=Base64.decode(s,Base64.DEFAULT);runOnUiThread(()->{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/octet-stream");i.putExtra(Intent.EXTRA_TITLE,"imperium_edited.sav");startActivityForResult(i,102);});}}
protected void onActivityResult(int req,int result,Intent intent){super.onActivityResult(req,result,intent);if(req==101){if(callback!=null){callback.onReceiveValue(result==RESULT_OK&&intent!=null?new Uri[]{intent.getData()}:null);callback=null;}}else if(req==102){if(result==RESULT_OK&&intent!=null&&pending!=null){try(OutputStream out=getContentResolver().openOutputStream(intent.getData())){out.write(pending);Toast.makeText(this,"저장 완료",1).show();}catch(Exception e){Toast.makeText(this,"저장 실패",1).show();}}pending=null;}}
}